INSERT INTO `archives` (`id`, `title`, `description`, `content`, `type`, `year`, `longitude`, `latitude`, `media_json`, `created_at`, `updated_at`) VALUES ('blood-field', '血田遗址', '1928年春，国民党反动派对紫金苏区进行残酷“围剿”。450多名红军指战员、苏维埃干部和革命群众在此惨遭集体杀害，烈士的鲜血染红了整片水田，“血田”由此得名。', '【思政大课堂：信仰的底色是忠诚】
INSERT INTO `archives` (`id`, `title`, `description`, `content`, `type`, `year`, `longitude`, `latitude`, `media_json`, `created_at`, `updated_at`) VALUES ('dongjiang-committee', '中共东江特委旧址', '中共东江特别委员会曾在此设址办公，统一领导海丰、陆丰、紫金、惠阳等县的革命斗争。这里是东江流域苏维埃运动的指挥中枢。', '【思政大课堂：一盘棋的革命战略】
INSERT INTO `archives` (`id`, `title`, `description`, `content`, `type`, `year`, `longitude`, `latitude`, `media_json`, `created_at`, `updated_at`) VALUES ('paozi-village-defense', '炮子村阻击战遗址', '1928年3月，红二师、红四师与苏区赤卫队在此依托山势地形与敌军展开殊死搏斗，以少敌多、以弱抗强，掩护了苏维埃政府和群众安全转移。这是一场可歌可泣的苏区保卫战。', '【思政大课堂：牺牲与担当】
INSERT INTO `archives` (`id`, `title`, `description`, `content`, `type`, `year`, `longitude`, `latitude`, `media_json`, `created_at`, `updated_at`) VALUES ('red-army-hospital', '红军医院旧址', '苏区军民在极端困难条件下自办的战地医疗所。没有药品，群众上山采草药；没有纱布，妇女撕开自己的被单煮沸消毒代用。', '【思政大课堂：生命至上的革命人道主义】
INSERT INTO `archives` (`id`, `title`, `description`, `content`, `type`, `year`, `longitude`, `latitude`, `media_json`, `created_at`, `updated_at`) VALUES ('red-army-pavilion', '红军亭', '中国工农革命军第二师（红二师）和第四师（红四师）在此驻扎、集结、誓师的重要场所。南昌起义军余部和广州起义军余部曾在此历史性会师。', '【思政大课堂：星火燎原的革命力量】
INSERT INTO `archives` (`id`, `title`, `description`, `content`, `type`, `year`, `longitude`, `latitude`, `media_json`, `created_at`, `updated_at`) VALUES ('scholar-culture-hall', '苏区红色书院', '依托苏区红色资源打造的学习教育基地。设有红色阅览室、党史大讲堂、VR沉浸式体验区，面向全社会免费开放。', '【思政大课堂：书香里的红色基因】
INSERT INTO `archives` (`id`, `title`, `description`, `content`, `type`, `year`, `longitude`, `latitude`, `media_json`, `created_at`, `updated_at`) VALUES ('soviet-arsenal', '苏维埃兵工厂遗址', '紫金苏维埃政权自行建立的武器修造工场。在敌人严密封锁下，苏区军民自力更生，在此制造和修理土枪、大刀、手榴弹等武器，为武装斗争提供了宝贵的后勤保障。', '【思政大课堂：自力更生的革命精神】
INSERT INTO `archives` (`id`, `title`, `description`, `content`, `type`, `year`, `longitude`, `latitude`, `media_json`, `created_at`, `updated_at`) VALUES ('suqu-education-base', '广东省党员教育基地 (苏区)', '中共广东省委组织部授牌的省级党员教育基地。每年接待来自全省各地的党员干部数万人次，开展党性教育和革命传统教育。', '【思政大课堂：锤炼党性的红色熔炉】
INSERT INTO `archives` (`id`, `title`, `description`, `content`, `type`, `year`, `longitude`, `latitude`, `media_json`, `created_at`, `updated_at`) VALUES ('suqu-mass-line-hall', '苏区群众路线教育实践馆', '面向全体人民的新时代思政教育大课堂。通过数字化技术让红色历史“活”起来，让苏区精神“传”下去，是全国红色村组织振兴的重要试点项目。', '【思政大课堂：新时代的红色传承】
INSERT INTO `archives` (`id`, `title`, `description`, `content`, `type`, `year`, `longitude`, `latitude`, `media_json`, `created_at`, `updated_at`) VALUES ('suqu-monument', '苏区革命烈士纪念碑', '1958年，经国务院批准，炮子乡正式命名为“苏区乡”（后改为苏区镇），成为全国唯一以“苏区”命名的乡镇。同年修建此碑以纪念历次革命战争中牺牲的苏区籍烈士。', '【思政大课堂：不忘初心，牢记使命】
INSERT INTO `archives` (`id`, `title`, `description`, `content`, `type`, `year`, `longitude`, `latitude`, `media_json`, `created_at`, `updated_at`) VALUES ('suqu-party-square', '苏区党建文化广场', '集党建宣传、群众文化、红色教育于一体的开放式公共空间。广场中心矗立着党徽雕塑，四周环绕着苏区革命历史浮雕墙。', '【思政大课堂：润物无声的红色文化】
INSERT INTO `archives` (`id`, `title`, `description`, `content`, `type`, `year`, `longitude`, `latitude`, `media_json`, `created_at`, `updated_at`) VALUES ('suqu-red-house', '紫金县苏维埃政府旧址 (红屋)', '1927年12月，在此召开了紫金县工农兵代表大会，宣告紫金县苏维埃政府成立。因会场内外张贴红联、悬挂红旗，群众亲切地称之为“红屋”。这是广东省最早成立的县级苏维埃政权之一。', '【思政大课堂：政权归于人民】
INSERT INTO `archives` (`id`, `title`, `description`, `content`, `type`, `year`, `longitude`, `latitude`, `media_json`, `created_at`, `updated_at`) VALUES ('suqu-red-transport-station', '苏区红色交通站旧址', '土地革命战争时期，中共中央建立的地下交通网络在苏区镇的重要节点。承担着传递情报、护送干部、运送物资等绝密任务，是连接东江苏区与中央苏区的"红色血脉"。', '【思政大课堂：隐蔽战线的忠诚】
INSERT INTO `archives` (`id`, `title`, `description`, `content`, `type`, `year`, `longitude`, `latitude`, `media_json`, `created_at`, `updated_at`) VALUES ('suqu-town-hall', '苏区镇人民政府', '全国唯一以“苏区”命名的乡镇——苏区镇的行政中心。从战火纷飞的革命老区到欣欣向荣的红色文旅名镇，见证了时代的伟大变迁。', '【从革命热土到振兴典范】
INSERT INTO `archives` (`id`, `title`, `description`, `content`, `type`, `year`, `longitude`, `latitude`, `media_json`, `created_at`, `updated_at`) VALUES ('zijin-farmers-association', '紫金县总农会旧址', '全国最早建立的农会组织之一，受彭湃同志海丰农民运动直接影响而成立。在这里，农民第一次团结起来，发出了“打倒土豪劣绅、一切权力归农会”的时代强音。', '【思政大课堂：唤醒千百万劳苦大众】
INSERT INTO `archives` (`id`, `title`, `description`, `content`, `type`, `year`, `longitude`, `latitude`, `media_json`, `created_at`, `updated_at`) VALUES ('zijin-party-committee', '中共紫金县委旧址', '大革命失败后，中共紫金县委秘密迁至炮子乡，在此领导了紫金县的武装暴动和苏维埃政权建设。彭湃同志曾多次在此主持会议、部署斗争。', '【思政大课堂：深山里的红色中枢】
