INSERT INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `workflow_id`, `current_step_id`, `created_by`, `updated_by`, `submitted_at`, `published_at`, `deleted_at`, `created_at`, `updated_at`) VALUES ('content-archive-suqu-mass-line-hall', 'archive', 'government', '["legacy-migrated"]', 'published', '苏区群众路线教育实践馆', '面向全体人民的新时代思政教育大课堂。通过数字化技术让红色历史“活”起来，让苏区精神“传”下去，是全国红色村组织振兴的重要试点项目。', 'attention', '["史实来源待复核"]', 'version-archive-suqu-mass-line-hall-1', 'version-archive-suqu-mass-line-hall-1', 'workflow-archive-default', NULL, 'system-migration', 'system-frontend-joint-debug', NULL, 1784471183327, NULL, 1784047448819, 1784471183327);
INSERT INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `workflow_id`, `current_step_id`, `created_by`, `updated_by`, `submitted_at`, `published_at`, `deleted_at`, `created_at`, `updated_at`) VALUES ('content-archive-suqu-monument', 'archive', 'revolution', '["legacy-migrated"]', 'published', '苏区革命烈士纪念碑', '1958年，经国务院批准，炮子乡正式命名为“苏区乡”（后改为苏区镇），成为全国唯一以“苏区”命名的乡镇。同年修建此碑以纪念历次革命战争中牺牲的苏区籍烈士。', 'attention', '["史实来源待复核"]', 'version-archive-suqu-monument-1', 'version-archive-suqu-monument-1', 'workflow-archive-default', NULL, 'system-migration', 'system-frontend-joint-debug', NULL, 1784471183327, NULL, 1784047448819, 1784471183327);
INSERT INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `workflow_id`, `current_step_id`, `created_by`, `updated_by`, `submitted_at`, `published_at`, `deleted_at`, `created_at`, `updated_at`) VALUES ('content-archive-suqu-party-square', 'archive', 'culture', '["legacy-migrated"]', 'published', '苏区党建文化广场', '集党建宣传、群众文化、红色教育于一体的开放式公共空间。广场中心矗立着党徽雕塑，四周环绕着苏区革命历史浮雕墙。', 'attention', '["史实来源待复核"]', 'version-archive-suqu-party-square-1', 'version-archive-suqu-party-square-1', 'workflow-archive-default', NULL, 'system-migration', 'system-frontend-joint-debug', NULL, 1784471183327, NULL, 1784047448819, 1784471183327);
INSERT INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `workflow_id`, `current_step_id`, `created_by`, `updated_by`, `submitted_at`, `published_at`, `deleted_at`, `created_at`, `updated_at`) VALUES ('content-archive-suqu-red-house', 'archive', 'revolution', '["legacy-migrated"]', 'published', '紫金县苏维埃政府旧址 (红屋)', '1927年12月，在此召开了紫金县工农兵代表大会，宣告紫金县苏维埃政府成立。因会场内外张贴红联、悬挂红旗，群众亲切地称之为“红屋”。这是广东省最早成立的县级苏维埃政权之一。', 'attention', '["史实来源待复核"]', 'version-archive-suqu-red-house-1', 'version-archive-suqu-red-house-1', 'workflow-archive-default', NULL, 'system-migration', 'system-frontend-joint-debug', NULL, 1784471183327, NULL, 1784047448819, 1784471183327);
INSERT INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `workflow_id`, `current_step_id`, `created_by`, `updated_by`, `submitted_at`, `published_at`, `deleted_at`, `created_at`, `updated_at`) VALUES ('content-archive-suqu-red-transport-station', 'archive', 'revolution', '["legacy-migrated"]', 'published', '苏区红色交通站旧址', '土地革命战争时期，中共中央建立的地下交通网络在苏区镇的重要节点。承担着传递情报、护送干部、运送物资等绝密任务，是连接东江苏区与中央苏区的"红色血脉"。', 'attention', '["史实来源待复核"]', 'version-archive-suqu-red-transport-station-1', 'version-archive-suqu-red-transport-station-1', 'workflow-archive-default', NULL, 'system-migration', 'system-frontend-joint-debug', NULL, 1784471183327, NULL, 1784047448819, 1784471183327);
INSERT INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `workflow_id`, `current_step_id`, `created_by`, `updated_by`, `submitted_at`, `published_at`, `deleted_at`, `created_at`, `updated_at`) VALUES ('content-archive-suqu-town-hall', 'archive', 'government', '["legacy-migrated"]', 'published', '苏区镇人民政府', '全国唯一以“苏区”命名的乡镇——苏区镇的行政中心。从战火纷飞的革命老区到欣欣向荣的红色文旅名镇，见证了时代的伟大变迁。', 'attention', '["史实来源待复核"]', 'version-archive-suqu-town-hall-1', 'version-archive-suqu-town-hall-1', 'workflow-archive-default', NULL, 'system-migration', 'system-frontend-joint-debug', NULL, 1784471183327, NULL, 1784047448819, 1784471183327);
INSERT INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `workflow_id`, `current_step_id`, `created_by`, `updated_by`, `submitted_at`, `published_at`, `deleted_at`, `created_at`, `updated_at`) VALUES ('content-archive-zijin-farmers-association', 'archive', 'revolution', '["legacy-migrated"]', 'published', '紫金县总农会旧址', '全国最早建立的农会组织之一，受彭湃同志海丰农民运动直接影响而成立。在这里，农民第一次团结起来，发出了“打倒土豪劣绅、一切权力归农会”的时代强音。', 'attention', '["史实来源待复核"]', 'version-archive-zijin-farmers-association-1', 'version-archive-zijin-farmers-association-1', 'workflow-archive-default', NULL, 'system-migration', 'system-frontend-joint-debug', NULL, 1784471183327, NULL, 1784047448819, 1784471183327);
INSERT INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `workflow_id`, `current_step_id`, `created_by`, `updated_by`, `submitted_at`, `published_at`, `deleted_at`, `created_at`, `updated_at`) VALUES ('content-archive-zijin-party-committee', 'archive', 'revolution', '["legacy-migrated"]', 'published', '中共紫金县委旧址', '大革命失败后，中共紫金县委秘密迁至炮子乡，在此领导了紫金县的武装暴动和苏维埃政权建设。彭湃同志曾多次在此主持会议、部署斗争。', 'attention', '["史实来源待复核"]', 'version-archive-zijin-party-committee-1', 'version-archive-zijin-party-committee-1', 'workflow-archive-default', NULL, 'system-migration', 'system-frontend-joint-debug', NULL, 1784471183327, NULL, 1784047448819, 1784471183327);
