DROP TABLE IF EXISTS `archives`;
CREATE TABLE `archives` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` longtext COLLATE utf8mb4_unicode_ci,
  `type` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `year` bigint NOT NULL,
  `longitude` double NOT NULL,
  `latitude` double NOT NULL,
  `media_json` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` bigint NOT NULL,
  `updated_at` bigint NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_archives_year` (`year`),
  KEY `idx_archives_type` (`type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

1928年3月，国民党反动派调集重兵，对海陆惠紫苏区发动残酷的“围剿”。在紫金苏区炮子村，红军第四师、第二师余部及苏区赤卫队依托地形进行了顽强阻击。由于敌我力量悬殊，弹尽粮绝，防线最终被突破。

【血洒苏区，浩气长存】
反动派进村后，对手无寸铁的革命群众、苏维埃干部和红军伤病员进行了惨绝人寰的大屠杀。据《紫金县志》记载，先后有450多名革命先烈在炮子村的一块水田中被集体杀害。烈士的鲜血染红了整片稻田，经久不褪，当地群众悲痛地将这块水田称为“血田”。

【赓续红色血脉】
血田是苏区军民用生命捍卫信仰的铁血见证。今天我们重温这段悲壮历史，就是要铭记先烈遗志，在新的长征路上坚定信念、勇毅前行。', 'revolution', 1928, 115.3385, 23.359, '[{"type":"image","url":"/images/archives/blood-field.jpg","caption":"血田遗址纪念碑——1928年450余名革命先烈在此壮烈牺牲"}]', 1784047448819, 1784047448819);
1928年，为统一领导东江流域的革命斗争，中共广东省委决定成立东江特别委员会。特委机关曾设在紫金炮子乡，彭湃同志任书记。在特委的统一领导下，海陆惠紫四县的苏维埃运动连成一片，形成了面积约3000平方公里、人口超百万的东江苏区。

【薪火相传】
东江特委在炮子乡期间，不仅指挥军事斗争，还创办了《东江红旗》等革命刊物，开办党校培训干部，领导土地改革，使东江苏区成为当时全国重要的革命根据地之一。', 'revolution', 1928, 115.3395, 23.361, '[{"type":"image","url":"/images/archives/dongjiang-committee.jpg","caption":"中共东江特委旧址——彭湃同志任书记，统一领导海陆惠紫四县东江苏区"}]', 1784047448819, 1784047448819);
1928年3月，国民党反动派纠集数千兵力分三路向炮子村苏区发起总攻。面对数倍于己的敌人，红二师、红四师余部及当地赤卫队共约600余人，在炮子村外围山头构筑防线，展开了长达三天三夜的殊死阻击。

【壮烈的阻击战】
战斗中，红军战士子弹打光了就用石头砸，石头用完了就拼刺刀、肉搏。赤卫队员黄木生拉响最后一颗手榴弹与数名敌军同归于尽。年仅16岁的红军小战士钟火妹在运送弹药途中中弹牺牲，牺牲时双手仍紧紧抱着弹药箱。三天后，苏维埃政府和大部分群众安全转移，但留守阻击的红军指战员几乎全部壮烈牺牲。

【永恒的精神丰碑】
炮子村阻击战是东江苏区保卫战中最壮烈的一页。先烈们用生命诠释了什么叫"牺牲小我、成就大我"。今天，当我们站在这片被鲜血浸染的土地上，更应当铭记：和平来之不易，幸福需要守护。', 'revolution', 1928, 115.333, 23.3585, '[{"type":"image","url":"/images/archives/paozi-village-defense.jpg","caption":"炮子村阻击战遗址——1928年600余名红军赤卫队员殊死阻击敌军三天三夜"}]', 1784047448819, 1784047448819);
1928年反“围剿”期间，大量红军伤员急需救治。紫金苏维埃政府在炮子乡设立了红军医院。说是医院，其实不过是几间茅草屋、几张木板床。但就是这样一个简陋的医疗所，在苏区群众的全力支持下，挽救了许多红军战士的生命。

【群众是真正的铜墙铁壁】
没有西药，当地草医郎中带领群众上山采集中草药；没有纱布绷带，苏区妇女把自己的被单撕开，用开水煮沸消毒后代替；没有手术器械，铁匠铺连夜打制。一位老阿婆把自己养了多年的老母鸡杀了炖汤，一口一口喂给重伤员。这所医院是军民鱼水情深的最生动写照。', 'revolution', 1928, 115.337, 23.36, '[{"type":"image","url":"/images/archives/red-army-hospital.jpg","caption":"红军医院旧址——军民一体的战地医疗所"}]', 1784047448819, 1784047448819);
红军亭位于苏维埃政府旧址红屋附近。1927年，南昌起义军余部在董朗、颜昌颐率领下进入海陆丰地区，改编为中国工农革命军第二师（红二师）。同年末，广州起义军余部在叶镛、徐向前率领下抵达紫金，改编为红四师。两支英雄部队在紫金苏区胜利会师，红军亭便是当年部队驻扎、集结、誓师出征的重要场所。

【军民鱼水情】
在红军亭驻扎期间，红军战士与苏区百姓同吃同住同劳动，结下了深厚的军民鱼水情。苏区群众自发为红军缝制军衣、筹集粮草、救护伤员。红军亭见证了中国革命在低潮时期，火种在偏远山区不仅没有熄灭，反而呈星火燎原之势的伟大历史转折。', 'revolution', 1927, 115.342, 23.3625, '[{"type":"image","url":"/images/archives/red-army-pavilion.jpg","caption":"红军亭——南昌起义与广州起义余部在此会师誓师"}]', 1784047448819, 1784047448819);
苏区红色书院是广东省推动红色文化传承的重点文化惠民工程。书院藏书三万余册，其中红色文献专题区收藏了大量珍贵的党史、革命史研究资料。书院定期邀请党史专家、老党员开展“苏区大讲堂”活动，面向青少年开办“小小讲解员”培训。

【全民阅读与红色教育融合】
书院的VR体验区通过数字技术，让参观者“穿越”回1927年的红屋，亲身感受苏维埃政权成立的庄严时刻。红色书院的建成为苏区红色教育注入了浓厚的文化气息，实现了从“参观式”到“沉浸式”学习体验的升级。', 'culture', 2023, 115.3415, 23.3595, '[{"type":"image","url":"/images/archives/scholar-culture-hall.jpg","caption":"苏区红色书院——藏书三万余册，VR体验区可沉浸式学党史"}]', 1784047448819, 1784047448819);
1928年，面对国民党反动派的军事“围剿”和经济封锁，紫金苏维埃政权在极其困难的条件下，于炮子乡深山之中秘密建立了兵工厂。没有钢材，就收集废铁熔炼；没有火药，就用土硝、硫磺、木炭自行配制；没有技术人员，就从铁匠、木匠中培养。

【群众的智慧与力量】
兵工厂虽然简陋，但在苏区军民的共同努力下，每月能修理步枪数十支、制造大刀长矛上百件、配制黑火药数十斤。这些看似简陋的武器，却成为了红军打击敌人的有力工具。兵工厂的历史告诉我们：只要紧紧依靠人民群众，就没有克服不了的困难。', 'revolution', 1928, 115.3365, 23.3575, '[{"type":"image","url":"/images/archives/soviet-arsenal.jpg","caption":"苏维埃兵工厂遗址——苏区军民自力更生制造土枪大刀"}]', 1784047448819, 1784047448819);
2019年，经中共广东省委组织部批准，苏区镇被列为广东省党员教育基地。基地整合了红屋、血田、红军亭、革命烈士纪念碑等核心红色资源，开发了“重走红军路”、“忆苦思甜饭”、“苏区精神专题党课”等一系列体验式教学课程。

【铸魂育人的实践探索】
基地创新推出了“看一次展览、听一次党课、走一次红军路、吃一顿红军餐、写一篇心得体会”的“五个一”教学模式，让党员干部在亲身体验中接受精神洗礼。', 'government', 2019, 115.346, 23.362, '[{"type":"image","url":"/images/archives/suqu-education-base.jpg","caption":"广东省党员教育基地（苏区）——‘五个一’教学模式锤炼党性"}]', 1784047448819, 1784047448819);
从昔日的革命老区到今天的数字孪生示范镇，这里是面向全体人民的思政教育中枢。教育馆通过虚拟现实、全息投影和在线互动技术，打破了时空限制，让全国乃至全世界的群众都能“云游”苏区、重温党史。

【数字化思政实践】
通过“线上致敬”、“党史学习”、“群众心声留言板”等互动形式，思政教育不再是单向的灌输，而是成为群众自发参与、自我教育的生动实践。这里实现了跨越百年的时空对话，让红色基因在数字时代焕发出更加璀璨的光芒。', 'government', 2020, 115.345, 23.358, '[{"type":"image","url":"/images/archives/suqu-mass-line-hall.jpg","caption":"苏区群众路线教育实践馆——全国红色村组织振兴试点"}]', 1784047448819, 1784047448819);
紫金县苏区镇是全国唯一以“苏区”命名的乡镇——这个独一无二的地名，本身就是一座永恒的丰碑。为了新中国的成立，苏区人民付出了极其惨重的代价。仅1928年一年间，苏区就有1500多名革命群众和红军指战员献出了宝贵生命。

【全民思政实践的精神高地】
1958年，为缅怀革命先烈，弘扬苏区精神，在此修建了“苏区革命烈士纪念碑”。碑身正面镌刻着“革命烈士永垂不朽”八个大字。

【新时代的担当】
今天，无论是共产党员、共青团员、少先队员还是普通群众，都在此缅怀先烈。这要求我们在新时代必须传承革命先辈“敢教日月换新天”的斗争精神，为实现中华民族伟大复兴的中国梦而不懈奋斗。', 'revolution', 1958, 115.343, 23.364, '[{"type":"image","url":"/images/archives/suqu-monument.jpg","caption":"苏区革命烈士纪念碑——全国唯一以‘苏区’命名乡镇的精神地标"}]', 1784047448819, 1784047448819);
苏区党建文化广场是苏区镇新时代基层党建和群众文化融合的典范。广场采用开放式设计，不设围墙，寓意“党与人民群众零距离”。广场上的革命历史浮雕墙以时间为轴，生动再现了1923年至1949年紫金苏区的革命历程。

【党群连心桥】
每逢七一、国庆等重要节点，广场上都会举行新党员入党宣誓、老党员重温誓词仪式。平日里，这里是群众跳广场舞、唱红歌、开展文化活动的欢乐场所。', 'culture', 2021, 115.344, 23.363, '[{"type":"image","url":"/images/archives/suqu-party-square.jpg","caption":"苏区党建文化广场——开放式设计不设围墙，寓意党与人民群众零距离"}]', 1784047448819, 1784047448819);
1927年4月，蒋介石发动四一二反革命政变。紫金县党组织按照中共中央和广东省委指示，组织武装暴动。1927年12月，在彭湃同志的直接指导下，紫金县工农兵代表大会在苏区镇（原炮子乡）林氏宗祠召开，正式宣告紫金县苏维埃政府成立。大会选举产生了执行委员会，主席为刘琴西。

【历史的回响】
红屋原为林氏宗祠，始建于清代。苏维埃政权在此办公期间，发布了《没收地主土地分给农民》等一系列纲领性文件，掀起了东江流域土地革命的高潮。红屋的建立，标志着紫金劳苦大众第一次真正把政权掌握在自己手中。

【启示与传承】
江山就是人民，人民就是江山。只有始终同人民群众同呼吸、共命运、心连心，党才能赢得人民的衷心拥护。红屋虽小，但它是中国苏维埃运动在广东的一面旗帜，见证了中国共产党人早期探索人民政权建设的伟大实践。', 'revolution', 1927, 115.3412, 23.3615, '[{"type":"image","url":"/images/archives/suqu-red-house.jpg","caption":"紫金县苏维埃政府旧址（红屋）——始建于清代的林氏宗祠，1927年成为苏维埃政权驻地"}]', 1784047448819, 1784047448819);
1928年至1934年间，中共中央建立了从上海经香港、汕头、大埔进入中央苏区的秘密交通线。紫金县苏区镇（炮子乡）是这条红色交通线的重要支线节点。交通员们化装成商贩、郎中、挑夫，冒着生命危险传递党的机密文件、护送领导干部、运送药品武器。

【无声的英雄】
交通站设在炮子村一间不起眼的杂货铺地下。交通员白天是普通百姓，夜晚则化身红色信使。据《东江革命根据地史》记载，经由苏区交通站护送的党政军领导干部达数十人，传递机密文件数百件。交通员李月梅在执行任务途中被捕，敌人严刑拷打，她至死没有吐露半个字。

【忠诚的底色】
红色交通站是革命战争年代的"隐秘动脉"，交通员们用生命和忠诚织就了一张无形的革命大网。他们的故事告诉我们：忠诚不是口号，而是生死关头的不变信仰。', 'revolution', 1928, 115.3425, 23.357, '[{"type":"image","url":"/images/archives/suqu-red-transport-station.jpg","caption":"苏区红色交通站旧址——连接东江苏区与中央苏区的秘密交通线节点"}]', 1784047448819, 1784047448819);
1958年，国务院正式批准将紫金县炮子乡命名为“苏区乡”（后改为苏区镇），这是全国唯一获此殊荣的乡镇。六十余年来，苏区镇党委政府一届接着一届干，带领苏区人民实现了从站起来、富起来到强起来的伟大飞跃。

【乡村振兴的苏区答卷】
近年来，苏区镇以红色文化为引领，大力发展红色旅游和特色农业，实现了全域脱贫奔康。宽阔的柏油路通到了每个自然村，新建的安置小区让老区人民住上了暖心房。', 'government', 1958, 115.348, 23.356, '[{"type":"image","url":"/images/archives/suqu-town-hall.jpg","caption":"苏区镇人民政府——全国唯一以‘苏区’命名的乡镇行政中心"}]', 1784047448819, 1784047448819);
1923年元旦，在海丰县总农会成立的影响下，紫金县的先进知识分子和农民骨干便开始秘密串联。同年春，紫金县总农会在炮子乡正式成立，成为东江地区继海丰之后第二个县级农会组织。

【群众路线的生动实践】
农会成立后，领导农民开展减租减息、反抗苛捐杂税的斗争，迅速将一盘散沙的农民凝聚成一股不可战胜的力量。农会推行的“二五减租”政策，使广大贫苦农民第一次感受到了组织的力量。

【历史启示】
农会的历史，就是一部生动的党的群众路线实践史。它深刻印证了：一切为了群众，一切依靠群众，从群众中来，到群众中去，是我们党的生命线和根本工作路线。', 'revolution', 1923, 115.3445, 23.3605, '[{"type":"image","url":"/images/archives/zijin-farmers-association.jpg","caption":"紫金县总农会旧址——1923年成立，东江地区最早的县级农会之一"}]', 1784047448819, 1784047448819);
1927年四一二反革命政变后，国民党反动派大肆屠杀共产党人和革命群众。中共紫金县委被迫从县城秘密迁至炮子乡深山之中。在极其艰苦的条件下，县委在此起草并发布了《紫金县武装暴动计划》，点燃了紫金土地革命的烽火。

【彭湃同志的紫金足迹】
时任中共东江特委书记的彭湃同志曾多次亲临此处，主持召开县委扩大会议，传达党的八七会议精神，指导紫金的武装斗争和土地革命。

【历史启示】
这个不起眼的深山驻地，是当年紫金革命斗争的指挥中枢。它告诉我们：只要坚持党的领导，再偏远的地方也能成为革命的坚强堡垒。', 'revolution', 1927, 115.34, 23.358, '[{"type":"image","url":"/images/archives/zijin-party-committee.jpg","caption":"中共紫金县委旧址——深山里的红色中枢，彭湃同志曾在此主持多次重要会议"}]', 1784047448819, 1784047448819);

DROP TABLE IF EXISTS `audit_logs`;
CREATE TABLE `audit_logs` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `action` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `entity_type` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `entity_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `before_json` longtext COLLATE utf8mb4_unicode_ci,
  `after_json` longtext COLLATE utf8mb4_unicode_ci,
  `actor` longtext COLLATE utf8mb4_unicode_ci,
  `ip` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` bigint NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_audit_entity` (`entity_type`,`entity_id`),
  KEY `idx_audit_created` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=1988 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `checkin_progress`;
CREATE TABLE `checkin_progress` (
  `visitor_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `visited_pois_json` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `updated_at` bigint NOT NULL,
  PRIMARY KEY (`visitor_id`),
  KEY `idx_checkin_progress_updated` (`updated_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `content_modules`;
CREATE TABLE `content_modules` (
  `module_key` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `default_publish_map` bigint NOT NULL DEFAULT '0',
  `default_publish_list` bigint NOT NULL DEFAULT '1',
  `default_publish_home` bigint NOT NULL DEFAULT '0',
  `default_publish_topic` bigint NOT NULL DEFAULT '0',
  `default_publish_guide` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`module_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `content_review_tasks`;
CREATE TABLE `content_review_tasks` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `version_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `workflow_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `step_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `assignee_role_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reviewer_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `comment` longtext COLLATE utf8mb4_unicode_ci,
  `created_at` bigint NOT NULL,
  `reviewed_at` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_review_tasks_content` (`content_id`),
  KEY `idx_review_tasks_status` (`status`,`assignee_role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `content_sources`;
CREATE TABLE `content_sources` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `version_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_type` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_title` longtext COLLATE utf8mb4_unicode_ci,
  `source_url` longtext COLLATE utf8mb4_unicode_ci,
  `archive_ref` longtext COLLATE utf8mb4_unicode_ci,
  `page_ref` longtext COLLATE utf8mb4_unicode_ci,
  `collector` longtext COLLATE utf8mb4_unicode_ci,
  `collected_at` longtext COLLATE utf8mb4_unicode_ci,
  `trust_level` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `attachment_media_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` longtext COLLATE utf8mb4_unicode_ci,
  `created_at` bigint NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_content_sources_content` (`content_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `content_versions`;
CREATE TABLE `content_versions` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `version_number` bigint NOT NULL,
  `title` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `summary` longtext COLLATE utf8mb4_unicode_ci,
  `body` longtext COLLATE utf8mb4_unicode_ci,
  `data_json` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_by` longtext COLLATE utf8mb4_unicode_ci,
  `created_at` bigint NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_content_versions_number` (`content_id`,`version_number`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

1928年3月，国民党反动派调集重兵，对海陆惠紫苏区发动残酷的“围剿”。在紫金苏区炮子村，红军第四师、第二师余部及苏区赤卫队依托地形进行了顽强阻击。由于敌我力量悬殊，弹尽粮绝，防线最终被突破。

【血洒苏区，浩气长存】
反动派进村后，对手无寸铁的革命群众、苏维埃干部和红军伤病员进行了惨绝人寰的大屠杀。据《紫金县志》记载，先后有450多名革命先烈在炮子村的一块水田中被集体杀害。烈士的鲜血染红了整片稻田，经久不褪，当地群众悲痛地将这块水田称为“血田”。

【赓续红色血脉】
血田是苏区军民用生命捍卫信仰的铁血见证。今天我们重温这段悲壮历史，就是要铭记先烈遗志，在新的长征路上坚定信念、勇毅前行。', '{"legacyId":"blood-field","type":"revolution","year":1928,"longitude":115.3385,"latitude":23.359,"media":[{"type":"image","url":"/images/archives/blood-field.jpg","caption":"血田遗址纪念碑——1928年450余名革命先烈在此壮烈牺牲"}],"regionId":"region-suqu","regionName":"苏区镇","archiveType":"revolution","coverImage":"/images/archives/blood-field.jpg","cover_image":"/images/archives/blood-field.jpg","publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false}}', 'system-migration', 1784047448819);
1928年，为统一领导东江流域的革命斗争，中共广东省委决定成立东江特别委员会。特委机关曾设在紫金炮子乡，彭湃同志任书记。在特委的统一领导下，海陆惠紫四县的苏维埃运动连成一片，形成了面积约3000平方公里、人口超百万的东江苏区。

【薪火相传】
东江特委在炮子乡期间，不仅指挥军事斗争，还创办了《东江红旗》等革命刊物，开办党校培训干部，领导土地改革，使东江苏区成为当时全国重要的革命根据地之一。', '{"legacyId":"dongjiang-committee","type":"revolution","year":1928,"longitude":115.3395,"latitude":23.361,"media":[{"type":"image","url":"/images/archives/dongjiang-committee.jpg","caption":"中共东江特委旧址——彭湃同志任书记，统一领导海陆惠紫四县东江苏区"}],"regionId":"region-suqu","regionName":"苏区镇","archiveType":"revolution","coverImage":"/images/archives/dongjiang-committee.jpg","cover_image":"/images/archives/dongjiang-committee.jpg","publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false}}', 'system-migration', 1784047448819);
1928年3月，国民党反动派纠集数千兵力分三路向炮子村苏区发起总攻。面对数倍于己的敌人，红二师、红四师余部及当地赤卫队共约600余人，在炮子村外围山头构筑防线，展开了长达三天三夜的殊死阻击。

【壮烈的阻击战】
战斗中，红军战士子弹打光了就用石头砸，石头用完了就拼刺刀、肉搏。赤卫队员黄木生拉响最后一颗手榴弹与数名敌军同归于尽。年仅16岁的红军小战士钟火妹在运送弹药途中中弹牺牲，牺牲时双手仍紧紧抱着弹药箱。三天后，苏维埃政府和大部分群众安全转移，但留守阻击的红军指战员几乎全部壮烈牺牲。

【永恒的精神丰碑】
炮子村阻击战是东江苏区保卫战中最壮烈的一页。先烈们用生命诠释了什么叫"牺牲小我、成就大我"。今天，当我们站在这片被鲜血浸染的土地上，更应当铭记：和平来之不易，幸福需要守护。', '{"legacyId":"paozi-village-defense","type":"revolution","year":1928,"longitude":115.333,"latitude":23.3585,"media":[{"type":"image","url":"/images/archives/paozi-village-defense.jpg","caption":"炮子村阻击战遗址——1928年600余名红军赤卫队员殊死阻击敌军三天三夜"}],"regionId":"region-suqu","regionName":"苏区镇","archiveType":"revolution","coverImage":"/images/archives/paozi-village-defense.jpg","cover_image":"/images/archives/paozi-village-defense.jpg","publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false}}', 'system-migration', 1784047448819);
1928年反“围剿”期间，大量红军伤员急需救治。紫金苏维埃政府在炮子乡设立了红军医院。说是医院，其实不过是几间茅草屋、几张木板床。但就是这样一个简陋的医疗所，在苏区群众的全力支持下，挽救了许多红军战士的生命。

【群众是真正的铜墙铁壁】
没有西药，当地草医郎中带领群众上山采集中草药；没有纱布绷带，苏区妇女把自己的被单撕开，用开水煮沸消毒后代替；没有手术器械，铁匠铺连夜打制。一位老阿婆把自己养了多年的老母鸡杀了炖汤，一口一口喂给重伤员。这所医院是军民鱼水情深的最生动写照。', '{"legacyId":"red-army-hospital","type":"revolution","year":1928,"longitude":115.337,"latitude":23.36,"media":[{"type":"image","url":"/images/archives/red-army-hospital.jpg","caption":"红军医院旧址——军民一体的战地医疗所"}],"regionId":"region-suqu","regionName":"苏区镇","archiveType":"revolution","coverImage":"/images/archives/red-army-hospital.jpg","cover_image":"/images/archives/red-army-hospital.jpg","publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false}}', 'system-migration', 1784047448819);
红军亭位于苏维埃政府旧址红屋附近。1927年，南昌起义军余部在董朗、颜昌颐率领下进入海陆丰地区，改编为中国工农革命军第二师（红二师）。同年末，广州起义军余部在叶镛、徐向前率领下抵达紫金，改编为红四师。两支英雄部队在紫金苏区胜利会师，红军亭便是当年部队驻扎、集结、誓师出征的重要场所。

【军民鱼水情】
在红军亭驻扎期间，红军战士与苏区百姓同吃同住同劳动，结下了深厚的军民鱼水情。苏区群众自发为红军缝制军衣、筹集粮草、救护伤员。红军亭见证了中国革命在低潮时期，火种在偏远山区不仅没有熄灭，反而呈星火燎原之势的伟大历史转折。', '{"legacyId":"red-army-pavilion","type":"revolution","year":1927,"longitude":115.342,"latitude":23.3625,"media":[{"type":"image","url":"/images/archives/red-army-pavilion.jpg","caption":"红军亭——南昌起义与广州起义余部在此会师誓师"}],"regionId":"region-suqu","regionName":"苏区镇","archiveType":"revolution","coverImage":"/images/archives/red-army-pavilion.jpg","cover_image":"/images/archives/red-army-pavilion.jpg","publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false}}', 'system-migration', 1784047448819);
苏区红色书院是广东省推动红色文化传承的重点文化惠民工程。书院藏书三万余册，其中红色文献专题区收藏了大量珍贵的党史、革命史研究资料。书院定期邀请党史专家、老党员开展“苏区大讲堂”活动，面向青少年开办“小小讲解员”培训。

【全民阅读与红色教育融合】
书院的VR体验区通过数字技术，让参观者“穿越”回1927年的红屋，亲身感受苏维埃政权成立的庄严时刻。红色书院的建成为苏区红色教育注入了浓厚的文化气息，实现了从“参观式”到“沉浸式”学习体验的升级。', '{"legacyId":"scholar-culture-hall","type":"culture","year":2023,"longitude":115.3415,"latitude":23.3595,"media":[{"type":"image","url":"/images/archives/scholar-culture-hall.jpg","caption":"苏区红色书院——藏书三万余册，VR体验区可沉浸式学党史"}],"regionId":"region-suqu","regionName":"苏区镇","archiveType":"culture","coverImage":"/images/archives/scholar-culture-hall.jpg","cover_image":"/images/archives/scholar-culture-hall.jpg","publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false}}', 'system-migration', 1784047448819);
1928年，面对国民党反动派的军事“围剿”和经济封锁，紫金苏维埃政权在极其困难的条件下，于炮子乡深山之中秘密建立了兵工厂。没有钢材，就收集废铁熔炼；没有火药，就用土硝、硫磺、木炭自行配制；没有技术人员，就从铁匠、木匠中培养。

【群众的智慧与力量】
兵工厂虽然简陋，但在苏区军民的共同努力下，每月能修理步枪数十支、制造大刀长矛上百件、配制黑火药数十斤。这些看似简陋的武器，却成为了红军打击敌人的有力工具。兵工厂的历史告诉我们：只要紧紧依靠人民群众，就没有克服不了的困难。', '{"legacyId":"soviet-arsenal","type":"revolution","year":1928,"longitude":115.3365,"latitude":23.3575,"media":[{"type":"image","url":"/images/archives/soviet-arsenal.jpg","caption":"苏维埃兵工厂遗址——苏区军民自力更生制造土枪大刀"}],"regionId":"region-suqu","regionName":"苏区镇","archiveType":"revolution","coverImage":"/images/archives/soviet-arsenal.jpg","cover_image":"/images/archives/soviet-arsenal.jpg","publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false}}', 'system-migration', 1784047448819);
2019年，经中共广东省委组织部批准，苏区镇被列为广东省党员教育基地。基地整合了红屋、血田、红军亭、革命烈士纪念碑等核心红色资源，开发了“重走红军路”、“忆苦思甜饭”、“苏区精神专题党课”等一系列体验式教学课程。

【铸魂育人的实践探索】
基地创新推出了“看一次展览、听一次党课、走一次红军路、吃一顿红军餐、写一篇心得体会”的“五个一”教学模式，让党员干部在亲身体验中接受精神洗礼。', '{"legacyId":"suqu-education-base","type":"government","year":2019,"longitude":115.346,"latitude":23.362,"media":[{"type":"image","url":"/images/archives/suqu-education-base.jpg","caption":"广东省党员教育基地（苏区）——‘五个一’教学模式锤炼党性"}],"regionId":"region-suqu","regionName":"苏区镇","archiveType":"government","coverImage":"/images/archives/suqu-education-base.jpg","cover_image":"/images/archives/suqu-education-base.jpg","publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false}}', 'system-migration', 1784047448819);
从昔日的革命老区到今天的数字孪生示范镇，这里是面向全体人民的思政教育中枢。教育馆通过虚拟现实、全息投影和在线互动技术，打破了时空限制，让全国乃至全世界的群众都能“云游”苏区、重温党史。

【数字化思政实践】
通过“线上致敬”、“党史学习”、“群众心声留言板”等互动形式，思政教育不再是单向的灌输，而是成为群众自发参与、自我教育的生动实践。这里实现了跨越百年的时空对话，让红色基因在数字时代焕发出更加璀璨的光芒。', '{"legacyId":"suqu-mass-line-hall","type":"government","year":2020,"longitude":115.345,"latitude":23.358,"media":[{"type":"image","url":"/images/archives/suqu-mass-line-hall.jpg","caption":"苏区群众路线教育实践馆——全国红色村组织振兴试点"}],"regionId":"region-suqu","regionName":"苏区镇","archiveType":"government","coverImage":"/images/archives/suqu-mass-line-hall.jpg","cover_image":"/images/archives/suqu-mass-line-hall.jpg","publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false}}', 'system-migration', 1784047448819);
紫金县苏区镇是全国唯一以“苏区”命名的乡镇——这个独一无二的地名，本身就是一座永恒的丰碑。为了新中国的成立，苏区人民付出了极其惨重的代价。仅1928年一年间，苏区就有1500多名革命群众和红军指战员献出了宝贵生命。

【全民思政实践的精神高地】
1958年，为缅怀革命先烈，弘扬苏区精神，在此修建了“苏区革命烈士纪念碑”。碑身正面镌刻着“革命烈士永垂不朽”八个大字。

【新时代的担当】
今天，无论是共产党员、共青团员、少先队员还是普通群众，都在此缅怀先烈。这要求我们在新时代必须传承革命先辈“敢教日月换新天”的斗争精神，为实现中华民族伟大复兴的中国梦而不懈奋斗。', '{"legacyId":"suqu-monument","type":"revolution","year":1958,"longitude":115.343,"latitude":23.364,"media":[{"type":"image","url":"/images/archives/suqu-monument.jpg","caption":"苏区革命烈士纪念碑——全国唯一以‘苏区’命名乡镇的精神地标"}],"regionId":"region-suqu","regionName":"苏区镇","archiveType":"revolution","coverImage":"/images/archives/suqu-monument.jpg","cover_image":"/images/archives/suqu-monument.jpg","publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false}}', 'system-migration', 1784047448819);
苏区党建文化广场是苏区镇新时代基层党建和群众文化融合的典范。广场采用开放式设计，不设围墙，寓意“党与人民群众零距离”。广场上的革命历史浮雕墙以时间为轴，生动再现了1923年至1949年紫金苏区的革命历程。

【党群连心桥】
每逢七一、国庆等重要节点，广场上都会举行新党员入党宣誓、老党员重温誓词仪式。平日里，这里是群众跳广场舞、唱红歌、开展文化活动的欢乐场所。', '{"legacyId":"suqu-party-square","type":"culture","year":2021,"longitude":115.344,"latitude":23.363,"media":[{"type":"image","url":"/images/archives/suqu-party-square.jpg","caption":"苏区党建文化广场——开放式设计不设围墙，寓意党与人民群众零距离"}],"regionId":"region-suqu","regionName":"苏区镇","archiveType":"culture","coverImage":"/images/archives/suqu-party-square.jpg","cover_image":"/images/archives/suqu-party-square.jpg","publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false}}', 'system-migration', 1784047448819);
1927年4月，蒋介石发动四一二反革命政变。紫金县党组织按照中共中央和广东省委指示，组织武装暴动。1927年12月，在彭湃同志的直接指导下，紫金县工农兵代表大会在苏区镇（原炮子乡）林氏宗祠召开，正式宣告紫金县苏维埃政府成立。大会选举产生了执行委员会，主席为刘琴西。

【历史的回响】
红屋原为林氏宗祠，始建于清代。苏维埃政权在此办公期间，发布了《没收地主土地分给农民》等一系列纲领性文件，掀起了东江流域土地革命的高潮。红屋的建立，标志着紫金劳苦大众第一次真正把政权掌握在自己手中。

【启示与传承】
江山就是人民，人民就是江山。只有始终同人民群众同呼吸、共命运、心连心，党才能赢得人民的衷心拥护。红屋虽小，但它是中国苏维埃运动在广东的一面旗帜，见证了中国共产党人早期探索人民政权建设的伟大实践。', '{"legacyId":"suqu-red-house","type":"revolution","year":1927,"longitude":115.3412,"latitude":23.3615,"media":[{"type":"image","url":"/images/archives/suqu-red-house.jpg","caption":"紫金县苏维埃政府旧址（红屋）——始建于清代的林氏宗祠，1927年成为苏维埃政权驻地"}],"regionId":"region-suqu","regionName":"苏区镇","archiveType":"revolution","coverImage":"/images/archives/suqu-red-house.jpg","cover_image":"/images/archives/suqu-red-house.jpg","publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false}}', 'system-migration', 1784047448819);
1928年至1934年间，中共中央建立了从上海经香港、汕头、大埔进入中央苏区的秘密交通线。紫金县苏区镇（炮子乡）是这条红色交通线的重要支线节点。交通员们化装成商贩、郎中、挑夫，冒着生命危险传递党的机密文件、护送领导干部、运送药品武器。

【无声的英雄】
交通站设在炮子村一间不起眼的杂货铺地下。交通员白天是普通百姓，夜晚则化身红色信使。据《东江革命根据地史》记载，经由苏区交通站护送的党政军领导干部达数十人，传递机密文件数百件。交通员李月梅在执行任务途中被捕，敌人严刑拷打，她至死没有吐露半个字。

【忠诚的底色】
红色交通站是革命战争年代的"隐秘动脉"，交通员们用生命和忠诚织就了一张无形的革命大网。他们的故事告诉我们：忠诚不是口号，而是生死关头的不变信仰。', '{"legacyId":"suqu-red-transport-station","type":"revolution","year":1928,"longitude":115.3425,"latitude":23.357,"media":[{"type":"image","url":"/images/archives/suqu-red-transport-station.jpg","caption":"苏区红色交通站旧址——连接东江苏区与中央苏区的秘密交通线节点"}],"regionId":"region-suqu","regionName":"苏区镇","archiveType":"revolution","coverImage":"/images/archives/suqu-red-transport-station.jpg","cover_image":"/images/archives/suqu-red-transport-station.jpg","publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false}}', 'system-migration', 1784047448819);
1958年，国务院正式批准将紫金县炮子乡命名为“苏区乡”（后改为苏区镇），这是全国唯一获此殊荣的乡镇。六十余年来，苏区镇党委政府一届接着一届干，带领苏区人民实现了从站起来、富起来到强起来的伟大飞跃。

【乡村振兴的苏区答卷】
近年来，苏区镇以红色文化为引领，大力发展红色旅游和特色农业，实现了全域脱贫奔康。宽阔的柏油路通到了每个自然村，新建的安置小区让老区人民住上了暖心房。', '{"legacyId":"suqu-town-hall","type":"government","year":1958,"longitude":115.348,"latitude":23.356,"media":[{"type":"image","url":"/images/archives/suqu-town-hall.jpg","caption":"苏区镇人民政府——全国唯一以‘苏区’命名的乡镇行政中心"}],"regionId":"region-suqu","regionName":"苏区镇","archiveType":"government","coverImage":"/images/archives/suqu-town-hall.jpg","cover_image":"/images/archives/suqu-town-hall.jpg","publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false}}', 'system-migration', 1784047448819);
1923年元旦，在海丰县总农会成立的影响下，紫金县的先进知识分子和农民骨干便开始秘密串联。同年春，紫金县总农会在炮子乡正式成立，成为东江地区继海丰之后第二个县级农会组织。

【群众路线的生动实践】
农会成立后，领导农民开展减租减息、反抗苛捐杂税的斗争，迅速将一盘散沙的农民凝聚成一股不可战胜的力量。农会推行的“二五减租”政策，使广大贫苦农民第一次感受到了组织的力量。

【历史启示】
农会的历史，就是一部生动的党的群众路线实践史。它深刻印证了：一切为了群众，一切依靠群众，从群众中来，到群众中去，是我们党的生命线和根本工作路线。', '{"legacyId":"zijin-farmers-association","type":"revolution","year":1923,"longitude":115.3445,"latitude":23.3605,"media":[{"type":"image","url":"/images/archives/zijin-farmers-association.jpg","caption":"紫金县总农会旧址——1923年成立，东江地区最早的县级农会之一"}],"regionId":"region-suqu","regionName":"苏区镇","archiveType":"revolution","coverImage":"/images/archives/zijin-farmers-association.jpg","cover_image":"/images/archives/zijin-farmers-association.jpg","publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false}}', 'system-migration', 1784047448819);
1927年四一二反革命政变后，国民党反动派大肆屠杀共产党人和革命群众。中共紫金县委被迫从县城秘密迁至炮子乡深山之中。在极其艰苦的条件下，县委在此起草并发布了《紫金县武装暴动计划》，点燃了紫金土地革命的烽火。

【彭湃同志的紫金足迹】
时任中共东江特委书记的彭湃同志曾多次亲临此处，主持召开县委扩大会议，传达党的八七会议精神，指导紫金的武装斗争和土地革命。

【历史启示】
这个不起眼的深山驻地，是当年紫金革命斗争的指挥中枢。它告诉我们：只要坚持党的领导，再偏远的地方也能成为革命的坚强堡垒。', '{"legacyId":"zijin-party-committee","type":"revolution","year":1927,"longitude":115.34,"latitude":23.358,"media":[{"type":"image","url":"/images/archives/zijin-party-committee.jpg","caption":"中共紫金县委旧址——深山里的红色中枢，彭湃同志曾在此主持多次重要会议"}],"regionId":"region-suqu","regionName":"苏区镇","archiveType":"revolution","coverImage":"/images/archives/zijin-party-committee.jpg","cover_image":"/images/archives/zijin-party-committee.jpg","publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false}}', 'system-migration', 1784047448819);

